CREATE OR REPLACE TABLE {{DATABASE}}.SILVER.CUSTOMERS AS SELECT CUSTOMER_ID,INITCAP(TRIM(FIRST_NAME)) FIRST_NAME,INITCAP(TRIM(LAST_NAME)) LAST_NAME,LOWER(TRIM(EMAIL)) EMAIL,SIGNUP_DATE,UPPER(TRIM(COUNTRY)) COUNTRY FROM {{DATABASE}}.BRONZE.CUSTOMERS WHERE CUSTOMER_ID IS NOT NULL;
CREATE OR REPLACE TABLE {{DATABASE}}.SILVER.PRODUCTS AS SELECT PRODUCT_ID,TRIM(PRODUCT_NAME) PRODUCT_NAME,UPPER(TRIM(CATEGORY)) CATEGORY,PRICE,ACTIVE FROM {{DATABASE}}.BRONZE.PRODUCTS WHERE PRODUCT_ID IS NOT NULL AND PRICE>=0;
CREATE OR REPLACE TABLE {{DATABASE}}.SILVER.ORDERS AS SELECT ORDER_ID,CUSTOMER_ID,ORDER_DATE,UPPER(TRIM(STATUS)) STATUS FROM {{DATABASE}}.BRONZE.ORDERS WHERE ORDER_ID IS NOT NULL AND CUSTOMER_ID IS NOT NULL;
CREATE OR REPLACE TABLE {{DATABASE}}.SILVER.SALES AS SELECT SALE_ID,ORDER_ID,PRODUCT_ID,QUANTITY,UNIT_PRICE,DISCOUNT,TOTAL_AMOUNT,ROUND(QUANTITY*UNIT_PRICE*(1-DISCOUNT),2) CALCULATED_TOTAL FROM {{DATABASE}}.BRONZE.SALES WHERE SALE_ID IS NOT NULL AND QUANTITY>0 AND UNIT_PRICE>=0;
